          MPToastUtils.showMessage('请输入Prompt内容');
          return false;
        }

        final request = MPCreateTemplateRequest(
          title: title,
          icon: _template!.icon ?? '',
          prompt: prompt,
          type: _category,
          setDefault: setDefault,
          templateId: _templateId,
        );
